-- Genuine schema exported from the pre-change version 6 Database implementation.
CREATE TABLE asset_price_preferences(chain_key VARCHAR, token_address VARCHAR, price_kind VARCHAR NOT NULL, exchange VARCHAR, market VARCHAR, market_type VARCHAR, fixed_price DOUBLE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(chain_key, token_address));
CREATE TABLE balance_points(pool_id VARCHAR, block_number BIGINT, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, asset0_balance DOUBLE NOT NULL, asset1_balance DOUBLE NOT NULL, PRIMARY KEY(pool_id, block_number));
CREATE TABLE balance_snapshots(pool_id VARCHAR, asset_position SMALLINT, block_number BIGINT NOT NULL, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, balance DOUBLE NOT NULL, PRIMARY KEY(pool_id, asset_position));
CREATE TABLE blocks(chain_id BIGINT, block_number BIGINT, block_hash VARCHAR NOT NULL, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(chain_id, block_number));
CREATE TABLE chain_rpc_overrides(chain_key VARCHAR PRIMARY KEY, rpc_url VARCHAR NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE envio_settings(singleton BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) PRIMARY KEY, api_key VARCHAR, rpm_limit INTEGER DEFAULT(30) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK(singleton), CHECK((rpm_limit > 0)));
CREATE TABLE pool_assets(pool_id VARCHAR, "position" SMALLINT, symbol VARCHAR NOT NULL, address VARCHAR NOT NULL, decimals SMALLINT NOT NULL, price_kind VARCHAR NOT NULL, exchange VARCHAR, market VARCHAR, market_type VARCHAR, fixed_price DOUBLE, PRIMARY KEY(pool_id, "position"));
CREATE TABLE pool_logs(pool_id VARCHAR, chain_id BIGINT, tx_hash VARCHAR, log_index BIGINT, block_number BIGINT NOT NULL, asset_position SMALLINT NOT NULL, signed_raw VARCHAR NOT NULL, signed_amount DOUBLE NOT NULL, sender VARCHAR NOT NULL, recipient VARCHAR NOT NULL, PRIMARY KEY(pool_id, chain_id, tx_hash, log_index));
CREATE TABLE pools(id VARCHAR PRIMARY KEY, "name" VARCHAR NOT NULL, chain_key VARCHAR NOT NULL, address VARCHAR NOT NULL, start_block BIGINT NOT NULL, contract_type VARCHAR NOT NULL, paused BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, config_revision INTEGER DEFAULT(1) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE price_enrichment_attempts(pool_id VARCHAR, tx_hash VARCHAR, asset_position SMALLINT, config_revision INTEGER, attempted_at TIMESTAMP WITH TIME ZONE NOT NULL, retry_after TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(pool_id, tx_hash, asset_position, config_revision));
CREATE TABLE raw_logs(chain_id BIGINT, tx_hash VARCHAR, log_index BIGINT, block_number BIGINT NOT NULL, block_hash VARCHAR NOT NULL, tx_index BIGINT NOT NULL, address VARCHAR NOT NULL, topic0 VARCHAR NOT NULL, topic1 VARCHAR, topic2 VARCHAR, topic3 VARCHAR, "data" VARCHAR NOT NULL, PRIMARY KEY(chain_id, tx_hash, log_index));
CREATE TABLE reference_prices(pool_id VARCHAR, tx_hash VARCHAR, asset_position SMALLINT, config_revision INTEGER NOT NULL, provider VARCHAR NOT NULL, market VARCHAR, market_type VARCHAR, target_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, source_trade_id VARCHAR, source_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, price DOUBLE NOT NULL, lag_ms BIGINT NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(pool_id, tx_hash, asset_position));
CREATE TABLE schema_meta("version" INTEGER NOT NULL);
CREATE TABLE swaps(pool_id VARCHAR, tx_hash VARCHAR, block_number BIGINT NOT NULL, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, asset0_delta DOUBLE NOT NULL, asset1_delta DOUBLE NOT NULL, counterparty VARCHAR, PRIMARY KEY(pool_id, tx_hash));
CREATE TABLE sync_state(pool_id VARCHAR PRIMARY KEY, next_block BIGINT NOT NULL, head_block BIGINT, finalized_block BIGINT, status VARCHAR NOT NULL, progress DOUBLE DEFAULT(0) NOT NULL, "error" VARCHAR, active_rpc VARCHAR, rebuild_requested BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, work_generation BIGINT DEFAULT(1) NOT NULL, last_success_at TIMESTAMP WITH TIME ZONE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
